const cfg = $('Config').first().json
const d = $('Decide').first().json
const L = d.lead
const raw = String(L.phone || '').trim()
const formatAllowed = /^\+?[\d\s().-]+$/.test(raw)
let digits = raw.replace(/\D/g, '')
let toNumber = ''
if (formatAllowed && raw.startsWith('+')) toNumber = '+' + digits
else if (formatAllowed && /^[2-9]\d{2}[2-9]\d{6}$/.test(digits)) toNumber = '+1' + digits
else if (formatAllowed && /^1[2-9]\d{2}[2-9]\d{6}$/.test(digits)) toNumber = '+' + digits
const fromNumber = String(cfg.twilioFromNumber || '').trim()
const validTo = /^\+[1-9]\d{7,14}$/.test(toNumber)
const validFrom = /^\+[1-9]\d{7,14}$/.test(fromNumber)
const message = 'Hey, it\'s Kaleel from BOXX Automations! Thanks so much for requesting your free audit. I just sent your framework to your email. If you\'d like help going through it, you can book a call here: ' + cfg.calendlyUrl + ' Thanks again, talk soon! Reply STOP to opt out.'
return [{ json: { canSend: validTo && validFrom && d.sendSMS1 === true && d.lead.sms_marketing_consent === true && d.smsConsent === true, toNumber, fromNumber, message,
  lead_id: L.lead_id, email: L.email, problem: !validTo ? 'invalid_recipient_phone' : !validFrom ? 'configure_twilio_from_number' : !d.smsConsent ? 'no_sms_consent' : '' } }]

const src = $('Build welcome SMS').first().json
const res = $input.first().json
const err = res.error || res
const code = String(err.code || err.errorCode || res.code || '')
const row = {email:src.email,sms_confirmation_status:'failed',sms_confirmation_at:new Date().toISOString()}
if (code === '21610') Object.assign(row,{sms_marketing_consent:'FALSE',sms_opted_out:'TRUE',sms_opt_out:'TRUE',sms_status:'unsubscribed',sms_opt_out_date:new Date().toISOString()})
return [{json:row}]
